const body = $json.body;
const text = ((body.comment && body.comment.body) || '').trim();
const m = text.match(/^\/merge(?:\s+(squash|rebase|merge))?\b/i);
const method = (m && m[1] ? m[1] : 'squash').toLowerCase();
return [{ json: {
  mergeMethod: method,
  prNumber: body.issue.number,
  repoOwner: body.repository.owner.login,
  repoName: body.repository.name,
  repoFull: body.repository.full_name,
  senderLogin: body.sender && body.sender.login,
  commentUrl: (body.comment && body.comment.html_url) || ''
}}];

const pr = $json;
const prev = $('Parse merge command').item.json;
const map = JSON.parse($env.N8N_AGENT_MAP || '{}');
const prAuthor = pr.user && pr.user.login;
const authorEntry = map[prAuthor];
const targetLogin = (authorEntry && authorEntry.role === 'implementer')
  ? prAuthor
  : $env.N8N_IMPLEMENTER_DEFAULT;
const entry = map[targetLogin];
if (!entry) {
  throw new Error(`N8N_AGENT_MAP missing implementer "${targetLogin}"`);
}
const qaLogin = $env.N8N_HUMAN_QA_LOGIN;
if (!qaLogin) {
  throw new Error('N8N_HUMAN_QA_LOGIN is not set');
}
return [{ json: {
  ...prev,
  prTitle: pr.title,
  prBody: pr.body || '',
  prUrl: pr.html_url,
  prHeadRef: pr.head.ref,
  prAuthor,
  host: entry.host,
  sshPort: entry.port,
  sshUser: entry.user,
  qaLogin
}}];
